    data = json.load(f)

def is_japanese_heavy(s):
    if not s: return False
    jp = len(re.findall(r'[぀-ヿ一-鿿]', s))
    return jp > len(s) * 0.15

def looks_mojibake(s):
    if not s: return False
    if is_japanese_heavy(s): return False
    # heuristic: lots of non-ascii but not japanese, or lots of accented latin chars
    non_ascii = len(re.findall(r'[^\x00-\x7F]', s))
    return non_ascii > 5

def try_decode(s):
    candidates = []
    for enc1 in ['latin1','cp1252']:
        for enc2 in ['utf-8','shift_jis','cp932','euc_jp']:
            try:
                b = s.encode(enc1)
                d = b.decode(enc2)
                if is_japanese_heavy(d):
                    candidates.append((d, f'{enc1}->{enc2}'))
            except Exception:
                pass
    return candidates[0] if candidates else (None, None)

for item in data:
    for field in ['title','desc','body']:
        s = item.get(field,'')
        if looks_mojibake(s):
            d, method = try_decode(s)
            if d:
                print(item['idx'], item['name'], field, 'FIXED', method)
            else:
                print(item['idx'], item['name'], field, 'FAILED', repr(s[:40]))
