python3 << 'EOF'
import json, re

with open('batches/batch_0041.json', encoding='utf-8') as f:
    data = json.load(f)

def is_japanese_heavy(s):
    if not s: return False
    jp = len(re.findall(r'[぀-ヿ一-鿿]', s))
    return jp > len(s) * 0.15

def score(s):
    if not s: return -1
    jp = len(re.findall(r'[぀-ヿ一-鿿]', s))
    bad = s.count('�')
    return jp - bad*5

def best_decode(s):
    if not s or is_japanese_heavy(s):
        return s
    candidates = [s]
    for enc1 in ['latin1','cp1252']:
        for enc2 in ['utf-8','shift_jis','cp932','euc_jp']:
            try:
                d = s.encode(enc1, errors='ignore').decode(enc2, errors='ignore')
                candidates.append(d)
            except Exception:
                pass
        # double pass utf8
        try:
            d1 = s.encode(enc1, errors='ignore').decode('utf-8', errors='ignore')
            candidates.append(d1)
        except Exception:
            pass
    best = max(candidates, key=score)
    return best

out = []
for item in data:
    fixed = dict(item)
    for field in ['title','desc','body']:
        fixed[field] = best_decode(item.get(field,''))
    out.append(fixed)

with open('batch_0041_decoded.json','w',encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=1)

# print summary of changed ones
for orig, fx in zip(data, out):
    if orig.get('title') != fx.get('title') or orig.get('body') != fx.get('body'):
        print(fx['idx'], fx['name'], '->', fx['title'][:50])
